  $('.session-preview').addEventListener('pointermove',e=>{if(!motionAllowed()||e.pointerType!=='mouse')return;const r=e.currentTarget.getBoundingClientRect();e.currentTarget.style.setProperty('--spot-x',e.clientX-r.left+'px');e.currentTarget.style.setProperty('--spot-y',e.clientY-r.top+'px')});$('.session-preview').addEventListener('pointerleave',e=>{e.currentTarget.style.removeProperty('--spot-x');e.currentTarget.style.removeProperty('--spot-y')});
