  function renderCourse(){const done=completedUnits();$('#courseList').innerHTML=lessons.map((l,i)=>{const draft=state.pendingRounds[l.id];return `<article class="course-unit"><div class="unit-meta"><span>${esc(local(l.stage))} · ${String(i+1).padStart(2,'0')}</span><span>${esc(draft?t('draftTasks',{n:draft.answers.length}):done.has(l.id)?t('completeUnit'):t('taskCount',{n:5}))}</span></div><h3>${esc(local(l.title))}</h3><p>${esc(local(l.summary))}</p><p class="outcome">${esc(t('outcome')+local(l.outcome))}</p><div class="chunks" lang="en">${l.chunks.map(c=>'<span>'+esc(c)+'</span>').join('')}</div><button class="btn btn-line" data-unit="${i}">${esc(t(draft?'resumeUnit':done.has(l.id)?'reviewUnit':'openUnit'))}</button></article>`}).join('');$$('[data-unit]').forEach(b=>b.addEventListener('click',()=>startUnit(Number(b.dataset.unit))))}
  function applyTranslations(){document.documentElement.lang=locale;document.title=locale==='en'?'Speak easy · SWT conversation practice':'Speak easy · 英语练习室';$('#languageSelect').value=locale;$$('[data-t]').forEach(e=>e.textContent=t(e.dataset.t));$$('[data-aria]').forEach(e=>e.setAttribute('aria-label',t(e.dataset.aria)));$$('[data-placeholder]').forEach(e=>e.placeholder=t(e.dataset.placeholder));$('#datePill').textContent=new Intl.DateTimeFormat(locale,{month:'long',day:'numeric',weekday:'short'}).format(new Date());$('#pageTitle').textContent=t(titles[$('.view.active').id]);$$('[data-score]').forEach((s,i)=>{const value=s.value;s.innerHTML='<option value="">'+esc(t('scoreChoose'))+'</option>'+t('scores'+(i+1)).map((label,n)=>`<option value="${n+1}">${n+1} · ${esc(label)}</option>`).join('');s.value=value});updateMotion();updateAudioSettings();idleVoiceStatus();renderHome();renderCourse();renderTaskLabels();renderStats();renderRescue();renderBank();if(feedback)renderFeedback();if(lastResult)renderResult();updateNavRail()}

    // Fixed neural-voice recordings keep pronunciation and timbre consistent across devices.
    // Slow readings are separate recordings, not pitch-shifted normal-speed playback.
    const speechAudio=$('#voicePlayer'),cueAudio=$('#cuePlayer'),audioKey='speak-easy-audio-v1';
    let spokenClip=null,cueToken=0,audioPreference={volume:.85,effects:true};
    try{const v=JSON.parse(localStorage.getItem(audioKey));if(v){if(Number.isFinite(v.volume))audioPreference.volume=Math.min(1,Math.max(0,v.volume));if(typeof v.effects==='boolean')audioPreference.effects=v.effects}}catch{}
    function updateAudioSettings(){speechAudio.volume=audioPreference.volume;cueAudio.volume=audioPreference.volume*.36;$('#audioVolume').value=Math.round(audioPreference.volume*100);$('#volumeReadout').textContent=Math.round(audioPreference.volume*100)+'%';$('#effectsEnabled').checked=audioPreference.effects;$('#audioSettingsLabel').textContent=audioPreference.volume===0?t('muted'):t('sound')}
