    function idleVoiceStatus(){$('#voiceStatus').textContent=!hasSpeechAssets?t('voiceNotIncluded'):Number($('#speechRate').value)<1?t('slowStatus'):t('naturalStatus');if(!hasSpeechAssets){$('#speechRate').disabled=true;$('#practiceMode option[value="challenge"]').disabled=true;$$('[data-t="voices"],[data-t="audioDisclosure"]').forEach(e=>e.textContent=t('voiceNotIncluded'));$$('[data-t="listenStep"]').forEach(e=>e.textContent=t('readStep'));$$('[data-t="listenHint"]').forEach(e=>e.textContent=t('readHint'))}}
    function resetVoiceButton(source){if(!source)return;source.classList.remove('is-playing');source.setAttribute('aria-pressed','false');if(source.dataset.voiceLabel!==undefined)source.textContent=source.dataset.voiceLabel;if(source.dataset.voiceAria)source.setAttribute('aria-label',source.dataset.voiceAria);else source.removeAttribute('aria-label');const path=source.querySelector('svg path');if(path?.dataset.voicePath)path.setAttribute('d',path.dataset.voicePath)}
    function stopSpeech(){speechToken++;speechAudio.onplaying=null;speechAudio.onended=null;speechAudio.onerror=null;speechAudio.pause();try{speechAudio.currentTime=0}catch{}resetVoiceButton(spokenClip?.source);spokenClip=null;speechAudio.dataset.state='idle';$$('.is-playing,.is-speaking').forEach(x=>x.classList.remove('is-playing','is-speaking'));idleVoiceStatus()}
    function stopCue(){cueToken++;cueAudio.onended=null;cueAudio.onerror=null;cueAudio.pause();try{cueAudio.currentTime=0}catch{}cueAudio.dataset.state='idle'}
    function playCue(name){
      const replay=$('#audioWrap audio');
      if(document.hidden||!audioPreference.effects||audioPreference.volume===0||spokenClip||recorder?.state==='recording'||(replay&&!replay.paused))return;
      if(!['start','saved','complete','time'].includes(name))return;
      stopCue();const token=cueToken;cueAudio.src='audio/cue-'+name+'.wav';cueAudio.volume=audioPreference.volume*.36;cueAudio.dataset.state='playing';cueAudio.onended=()=>{if(token===cueToken)cueAudio.dataset.state='idle'};cueAudio.onerror=()=>{if(token===cueToken)cueAudio.dataset.state='error'};cueAudio.play().catch(()=>{if(token===cueToken)cueAudio.dataset.state='idle'});
    }
    function speak(clipId,source){
      if(!hasSpeechAssets){toast(t('voiceNotIncluded'));return}
      if(recorder?.state==='recording'){toast(t('recordFirst'));return}
      if(audioPreference.volume===0){toast(t('unmute'));return}
      if(!/^(q|rescue|bank|example|follow)-\d+$/.test(clipId))return;
      if(spokenClip?.clipId===clipId&&spokenClip.source===source){stopSpeech();return}
      stopSpeech();stopCue();$('#audioWrap audio')?.pause();const token=speechToken,variant=Number($('#speechRate').value)<1?'slow':'natural';spokenClip={clipId,source,variant};
      if(source){if(source.dataset.voiceAria===undefined)source.dataset.voiceAria=source.getAttribute('aria-label')||'';if(!source.querySelector('svg')&&source.dataset.voiceLabel===undefined)source.dataset.voiceLabel=source.textContent;source.setAttribute('aria-label',t('stopSpeech'));source.setAttribute('aria-pressed','true');source.classList.add('is-playing');if(source.dataset.voiceLabel!==undefined)source.textContent=t('stopSpeech');const path=source.querySelector('svg path');if(path){path.dataset.voicePath=path.dataset.voicePath||path.getAttribute('d');path.setAttribute('d','M8 8h8v8H8z')}}
      speechAudio.src='audio/'+clipId+'-'+variant+'.mp3';speechAudio.playbackRate=1;speechAudio.volume=audioPreference.volume;speechAudio.dataset.state='loading';$('#voiceStatus').textContent=t('voiceLoading');
      const fail=()=>{if(token!==speechToken)return;stopSpeech();speechAudio.dataset.state='error';toast(t('voiceFail'))};
      speechAudio.onplaying=()=>{if(token!==speechToken)return;speechAudio.dataset.state='playing';if(source?.id==='previewListen'){$('.sound-bars').classList.add('is-playing');$('.initial').classList.add('is-speaking')}$('#voiceStatus').textContent=/^(q|follow)-/.test(clipId)?t('jamieSpeaking'):t('miaSpeaking')};
      speechAudio.onended=()=>{if(token===speechToken)stopSpeech()};speechAudio.onerror=fail;speechAudio.play().catch(e=>{if(e.name!=='AbortError')fail()});
    }
    $('#audioVolume').addEventListener('input',()=>{audioPreference.volume=Number($('#audioVolume').value)/100;saveAudioSettings();if(audioPreference.volume===0){stopSpeech();stopCue()}});
    $('#effectsEnabled').addEventListener('change',()=>{audioPreference.effects=$('#effectsEnabled').checked;saveAudioSettings();if(!audioPreference.effects)stopCue()});
    $('#auditionInterviewer').addEventListener('click',e=>speak('q-2',e.currentTarget));$('#auditionCoach').addEventListener('click',e=>speak('rescue-0',e.currentTarget));
    $('#auditionEffects').addEventListener('click',()=>{if(!audioPreference.effects||audioPreference.volume===0){toast(t('enableEffects'));return}stopSpeech();playCue('complete')});
    $('#speechRate').addEventListener('change',()=>{const clip=spokenClip;stopSpeech();if(clip)speak(clip.clipId,clip.source)});
    document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#audioSettings').open=false});document.addEventListener('pointerdown',e=>{if(!$('#audioSettings').contains(e.target))$('#audioSettings').open=false});updateAudioSettings();


  function stopRecorder(){microphoneTicket++;const recording=recorder;recorder=null;try{if(recording&&recording.state!=='inactive')recording.stop()}catch{}finally{stream?.getTracks().forEach(track=>track.stop());stream=null;$('#recordBtn').classList.remove('recording');$('#recordBtn span').textContent=t('record')}}
  function cleanAudio(){if(recordUrl){URL.revokeObjectURL(recordUrl);recordUrl=null}$('#audioWrap').replaceChildren()}
  function pauseTimer(){clearInterval(timerId);timerId=null;$('#timer').classList.remove('is-running');$('#startTimer').textContent=t(seconds===60?'timerStart':seconds>0?'timerResume':'timerAgain')}
  function resetTimer(){pauseTimer();seconds=60;$('#timer').textContent='01:00';$('#startTimer').textContent=t('timerStart')}
