  function renderTaskLabels(){const {task,lesson}=allTasks[current];$('#questionTag').textContent=local(lesson.title);$('#questionText').textContent=task.prompt;$('#questionCue').textContent=local(task.context);$('#frameworkBox').textContent=task.frame;$('#exampleText').textContent=task.model;$('#taskTip').textContent=local(task.tip);$('#followText').textContent=task.followUp;$('#modeDescription').textContent=local(lesson.summary);$('#modeHint').textContent=t($('#practiceMode').value==='challenge'?'challengeHint':'guidedHint');$('#roundLabel').textContent=round?t('inRound',{unit:lessons.indexOf(lesson)+1,n:round.position+1}):t('single');$('#stepper').innerHTML=round?Array.from({length:5},(_,n)=>'<span class="'+(n<round.position?'done':n===round.position?'current':'')+'"></span>').join(''):'';$('#stepper').setAttribute('aria-label',round?t('inRound',{unit:lessons.indexOf(lesson)+1,n:round.position+1}):t('single'));$('#showTranslation').textContent=t($('#questionCue').hidden?'showContext':'hideContext');$('#showFramework').textContent=t($('#frameworkBox').hidden?'showFrame':'hideFrame');$('#showExample').textContent=t($('#exampleBox').hidden?'showExample':'hideExample');$('#showFollow').textContent=t($('#followBox').hidden?'showFollow':'hideFollow');$('#saveAnswer').textContent=t(round?(round.position===4?'saveFinish':'saveNext'):'saveSingle');$('#startTimer').textContent=t(timerId?'timerPause':seconds===60?'timerStart':seconds>0?'timerResume':'timerAgain');$('#recordBtn span').textContent=t(recorder?.state==='recording'?'stopRecord':'record');$('#showExample').disabled=$('#practiceMode').value==='challenge'&&$('#rubric').hidden;$('#showFramework').disabled=$('#practiceMode').value==='challenge'&&$('#rubric').hidden;const checks=$$('#taskChecks input').map(c=>c.checked);$('#taskChecks').innerHTML=task.checks.map((c,i)=>`<li><label><input type="checkbox" ${checks[i]?'checked':''}><span>${esc(local(c))}</span></label></li>`).join('');const replayNote=$('#audioWrap p');if(replayNote)replayNote.textContent=t('replayNote')}
  function renderQuestion(index){if(!Number.isInteger(index)||!allTasks[index])throw new Error('Unknown task');pausePractice();stopRecorder();cleanAudio();stopSpeech();stopCue();questionRevision++;current=index;$('#interviewSheet').hidden=false;$('#roundResult').hidden=true;['#questionCue','#frameworkBox','#rubric','#exampleBox','#followBox','#feedbackOutput'].forEach(s=>$(s).hidden=true);['#point1','#point2','#point3','#oneChange','#typedAnswer'].forEach(s=>$(s).value='');$$('[data-score]').forEach(s=>s.value='');$('#taskChecks').replaceChildren();feedback=null;feedbackText='';resetTimer();activeElapsed=0;questionInProgress=true;applyMode();renderTaskLabels();resumePractice();if(motionAllowed())$('#questionText').animate([{opacity:0,filter:'blur(4px)',transform:'translateY(9px)'},{opacity:1,filter:'blur(0)',transform:'none'}],{duration:380});$('#randomQuestion').hidden=!!round}
  function applyMode(){if(!hasSpeechAssets)$('#practiceMode').value='guided';const challenge=$('#practiceMode').value==='challenge';$('#questionText').hidden=challenge;$('#listenFirst').hidden=!challenge;$('#showQuestion').hidden=!challenge;if(challenge&&$('#rubric').hidden){$('#exampleBox').hidden=true;$('#frameworkBox').hidden=true}renderTaskLabels()}
  function startUnit(index){if(!Number.isInteger(index)||!lessons[index])throw new Error('Unknown unit');const lesson=lessons[index],draft=state.pendingRounds[lesson.id];round={lessonId:lesson.id,order:lesson.tasks.map(q=>allTasks.findIndex(x=>x.task.id===q.id)),position:draft?.answers.length??0,answers:draft?draft.answers.map(a=>({...a})):[]};if(draft)$('#practiceMode').value=draft.mode;renderQuestion(round.order[round.position]);showView('simulator');playCue('start')}
