  async function toggleRecord(){
    if(recorder?.state==='recording'){stopRecorder();return}
    if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast(t('recordUnsupported'));return}
    const startRevision=questionRevision,ticket=++microphoneTicket;
    stopSpeech();stopCue();$('#audioWrap audio')?.pause();$('#recordBtn').disabled=true;
    try{
      const source=await navigator.mediaDevices.getUserMedia({audio:true});
      if(ticket!==microphoneTicket||questionRevision!==startRevision||document.hidden||!$('#simulator').classList.contains('active')){source.getTracks().forEach(track=>track.stop());return}
      stream=source;cleanAudio();const parts=[],recording=new MediaRecorder(source);recorder=recording;
      recording.ondataavailable=e=>{if(e.data.size)parts.push(e.data)};
      recording.onstop=()=>{source.getTracks().forEach(track=>track.stop());if(questionRevision!==startRevision||(recorder&&recorder!==recording))return;const blob=new Blob(parts,{type:recording.mimeType});recordUrl=URL.createObjectURL(blob);const audio=document.createElement('audio');audio.controls=true;audio.src=recordUrl;audio.addEventListener('play',()=>{stopSpeech();stopCue()});const note=document.createElement('p');note.textContent=t('replayNote');$('#audioWrap').replaceChildren(audio,note)};
      recording.onerror=()=>{stopRecorder();toast(t('recordError'))};recording.start();$('#recordBtn').classList.add('recording');$('#recordBtn span').textContent=t('stopRecord');
    }catch{stopRecorder();toast(t('recordDenied'))}finally{$('#recordBtn').disabled=false}
  }
