  function formatDuration(s){return s<60?t('seconds',{n:Math.floor(s)}):t('duration',{m:Math.floor(s/60),s:Math.floor(s%60)})}
  function renderResult(){if(lastResult)$('#roundSummary').textContent=t('roundSummary',{n:lastResult.n,time:formatDuration(lastResult.seconds),score:lastResult.score})}
  function celebrate(){if(!motionAllowed())return;for(let i=0;i<10;i++){const p=document.createElement('span');p.className='confetti';p.setAttribute('aria-hidden','true');p.style.background=i%2?'#ce422a':'#7b9878';$('#roundResult').append(p);const a=p.animate([{opacity:0,transform:'scale(.4)'},{opacity:.9,offset:.2},{opacity:0,transform:`translate(${Math.cos(i*Math.PI/5)*45}px,${Math.sin(i*Math.PI/5)*38}px) rotate(${i*43}deg)`}],{duration:850,delay:150});a.onfinish=()=>p.remove();a.oncancel=()=>p.remove()}$('#roundResult').scrollIntoView({block:'nearest',behavior:'smooth'})}
  function renderStats(){const n=state.sessions.length,done=completedUnits();$('#sessionsStat').textContent=n;$('#minutesStat').textContent=Math.floor(state.totalSeconds/60);$('#scoreStat').textContent=n?state.sessions[0].score:'—';$('#phaseText').textContent=done.size+' / 8';$('#phaseTrack').innerHTML=lessons.map(l=>'<span class="'+(done.has(l.id)?'done':'')+'" title="'+esc(local(l.title))+'"></span>').join('');const history=$('#history');history.replaceChildren();if(!n)history.innerHTML='<p class="source-note">'+esc(t('emptyHistory'))+'</p>';state.sessions.slice(0,20).forEach(s=>{const l=lessons.find(l=>l.id===s.lessonId),date=new Date(s.date),label=Number.isFinite(date.getTime())?new Intl.DateTimeFormat(locale,{month:'2-digit',day:'2-digit'}).format(date):'—';const row=document.createElement('div');row.className='history-row';row.innerHTML='<span class="history-date">'+esc(label)+'</span><div><b>'+esc(l?local(l.title):s.title)+'</b><small>'+esc(t('taskCount',{n:s.questions??1})+' · '+formatDuration(s.seconds)+(s.notes.length?' · '+t('nextNote')+s.notes[0]:''))+'</small></div><span class="score">'+esc(s.score)+' / 4</span>';history.append(row)});const latest=new Map();for(const s of state.sessions)for(const a of s.answers??[])if(!latest.has(a.taskId))latest.set(a.taskId,a);const weak=[...latest.values()].filter(a=>a.score<3&&allTasks.some(x=>x.task.id===a.taskId));$('#reviewQueue').innerHTML=weak.length?weak.map(a=>{const index=allTasks.findIndex(x=>x.task.id===a.taskId);return '<button class="btn btn-line" data-review-task="'+index+'">'+esc(local(allTasks[index].lesson.title)+' · '+allTasks[index].task.id.split('-')[1])+'</button>'}).join(''):'<p class="source-note">'+esc(t('emptyQueue'))+'</p>';$$('[data-review-task]').forEach(b=>b.addEventListener('click',()=>{round=null;renderQuestion(Number(b.dataset.reviewTask));showView('simulator')}))}
  function renderRescue(){const previous=$$('#rescueGrid input').map(e=>e.value),revealed=$$('#rescueGrid .phrase-answer').map(e=>!e.hidden);$('#rescueGrid').innerHTML=rescue.map((r,i)=>`<article class="phrase-row"><div class="phrase-number">${String(i+1).padStart(2,'0')} / KEEP GOING</div><h3>${esc(local(r.scenario))}</h3><input maxlength="500" aria-label="${esc(t('phraseAnswer',{n:i+1}))}" placeholder="${esc(t('yourPhrase'))}" value="${esc(previous[i]??'')}"><div class="phrase-reveal"><p>${esc(local(r.hint))}</p><button class="btn-text" data-reveal="${i}">${esc(t(revealed[i]?'hidePhrase':'reveal'))}</button></div><div class="phrase-answer" id="rescue-${i}" ${revealed[i]?'':'hidden'}><p lang="en">${esc(r.answer)}</p><button class="btn-text" data-speak-rescue="${i}">${esc(t('shadow'))}</button></div></article>`).join('');$$('[data-reveal]').forEach(b=>b.addEventListener('click',()=>{const box=$('#rescue-'+b.dataset.reveal);box.hidden=!box.hidden;b.textContent=t(box.hidden?'reveal':'hidePhrase')}));$$('[data-speak-rescue]').forEach(b=>b.addEventListener('click',()=>speak('rescue-'+b.dataset.speakRescue,b)))}
  function renderBank(){const cats=[...new Map(bank.map(x=>[x.category.en,x.category])).entries()];$('#bankToolbar').innerHTML='<button class="filter '+(bankFilter==='*'?'active':'')+'" data-cat="*">'+esc(t('all'))+'</button>'+cats.map(([key,label])=>'<button class="filter '+(key===bankFilter?'active':'')+'" data-cat="'+esc(key)+'">'+esc(local(label))+'</button>').join('');$('#bankList').innerHTML=bank.flatMap((x,i)=>bankFilter==='*'||bankFilter===x.category.en?[`<article class="bank-row"><span class="small-caps">${esc(local(x.category))}</span><div><p class="english" lang="en">${esc(x.en)}</p><p class="chinese">${esc(local(x.note))}</p></div><button class="mini-play" data-bank-speak="${i}" aria-label="${esc(t('readPhrase',{n:i+1}))}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 5 10 7-10 7z"/></svg></button></article>`]:[]).join('');$$('[data-cat]').forEach(b=>b.addEventListener('click',()=>{stopSpeech();bankFilter=b.dataset.cat;renderBank()}));$$('[data-bank-speak]').forEach(b=>b.addEventListener('click',()=>speak('bank-'+b.dataset.bankSpeak,b)))}
  function registerWebMCP(){const ctx=document.modelContext;if(!ctx?.registerTool)return;const register=tool=>{try{Promise.resolve(ctx.registerTool(tool)).catch(()=>{})}catch{}};register({name:'get_swt_progress',title:'Read SWT practice progress',description:'Read device-local self-ratings, completed units and actual practice time. Not official or AI scores.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({sessions:state.sessions.length,totalSeconds:state.totalSeconds,completedUnits:[...completedUnits()],lastSelfRating:state.sessions[0]?.score??null,currentQuestion:questionInProgress?allTasks[current].task.prompt:null})});register({name:'start_swt_practice',title:'Start SWT practice',description:'Start a five-task core unit. Without a unit ID, start the integrated mock interview.',inputSchema:{type:'object',properties:{lessonId:{type:'string',enum:lessons.map(l=>l.id)}},additionalProperties:false},execute:(input={})=>{if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).some(k=>k!=='lessonId'))throw new Error('Invalid input');const index=input.lessonId===undefined?7:lessons.findIndex(l=>l.id===input.lessonId);if(index<0)throw new Error('Unknown unit');startUnit(index);return {started:true,question:allTasks[current].task.prompt}}});register({name:'complete_swt_answer',title:'Save an SWT self-rating',description:'Save four genuine self-ratings and one optional improvement note. Does not assess learner ability.',inputSchema:{type:'object',properties:{scores:{type:'array',items:{type:'integer',minimum:1,maximum:4},minItems:4,maxItems:4},note:{type:'string',maxLength:500}},required:['scores'],additionalProperties:false},execute:input=>{if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).some(k=>!['scores','note'].includes(k)))throw new Error('Invalid input');return recordAnswer(input.scores,input.note??'')}})}
  $$('[data-view]').forEach(b=>b.addEventListener('click',()=>showView(b.dataset.view)));
  $('#languageSelect').addEventListener('change',()=>{stopSpeech();stopCue();locale=$('#languageSelect').value;try{localStorage.setItem('speak-easy-locale',locale)}catch{}$$('[data-voice-label],[data-voice-aria]').forEach(b=>{delete b.dataset.voiceLabel;delete b.dataset.voiceAria});applyTranslations()});
  $('#motionToggle').addEventListener('click',()=>{if(systemMotion.matches){toast(t('motionSystem'));return}motionPreferred=!motionPreferred;try{localStorage.setItem('speak-easy-motion',motionPreferred?'on':'off')}catch{}updateMotion()});systemMotion.addEventListener('change',updateMotion);
  $('#startDay7').addEventListener('click',()=>startUnit(recommended()));$('#startMock').addEventListener('click',()=>startUnit(7));$('#nextLesson').addEventListener('click',()=>startUnit(recommended()));$('#previewListen').addEventListener('click',()=>{const lesson=lessons[recommended()],position=state.pendingRounds[lesson.id]?.answers.length??0;speak(lesson.tasks[position].audio,$('#previewListen'))});$('#listenQuestion').addEventListener('click',()=>speak(allTasks[current].task.audio,$('#listenQuestion')));$('#listenExample').addEventListener('click',()=>speak(allTasks[current].task.exampleAudio,$('#listenExample')));$('#listenFollow').addEventListener('click',()=>speak(allTasks[current].task.followAudio,$('#listenFollow')));$('#randomQuestion').addEventListener('click',randomQuestion);$('#startTimer').addEventListener('click',startTimer);$('#recordBtn').addEventListener('click',toggleRecord);$('#completeQuestion').addEventListener('click',openReview);
  $('#practiceMode').addEventListener('change',()=>{stopSpeech();applyMode()});$('#showQuestion').addEventListener('click',()=>{$('#questionText').hidden=false;$('#listenFirst').hidden=true;$('#showQuestion').hidden=true});
  for(const [button,box] of [['showTranslation','questionCue'],['showFramework','frameworkBox'],['showExample','exampleBox'],['showFollow','followBox']])$('#'+button).addEventListener('click',()=>{$('#'+box).hidden=!$('#'+box).hidden;renderTaskLabels()});
  $('#checkAnswer').addEventListener('click',checkText);$('#typedAnswer').addEventListener('input',()=>{if(feedback)renderFeedback()});
  $('#saveAnswer').addEventListener('click',()=>{try{recordAnswer($$('[data-score]').map(s=>Number(s.value)),$('#oneChange').value.trim())}catch(e){toast(e.message)}});$('#resetProgress').addEventListener('click',()=>{if(confirm(t('confirmReset'))&&save(empty())){round=null;renderTaskLabels();toast(t('resetDone'))}});
  window.addEventListener('pagehide',()=>{stopRecorder();stopSpeech();stopCue()});document.addEventListener('visibilitychange',()=>{if(document.hidden){pausePractice();stopRecorder();stopSpeech();stopCue();$('#audioWrap audio')?.pause();pauseTimer()}else resumePractice()});
  renderQuestion(0);questionInProgress=false;activeStarted=0;activeElapsed=0;applyTranslations();registerWebMCP();
